SELECT COUNT(*)
FROM report
WHERE reporter_id = #{reporterId}
  AND created_at >= #{since}

SELECT EXISTS(
    SELECT 1
    FROM report
    WHERE reporter_id = #{reporterId}
      AND target_type = #{targetType}
      AND target_id = #{targetId}
      AND status IN (0, 1)
)

SELECT EXISTS(
    SELECT 1
    FROM report
    WHERE target_type = #{targetType}
      AND target_id = #{targetId}
      AND status IN (0, 1)
)
